css:
[data-bz-section="location-hero"] { position: relative; overflow: hidden; min-height: 460px; display: flex; align-items: center; background: #111; color: #fff; text-align: center }
[data-bz-section="location-hero"] [data-bz-node^="lh-photo"],
[data-bz-section="location-hero"] [data-bz-node^="lh-banner"] { position: absolute; inset: 0; z-index: 0; margin: 0 }
[data-bz-section="location-hero"] [data-bz-node^="lh-photo"] img,
[data-bz-section="location-hero"] [data-bz-node^="lh-banner"] img { width: 100%; height: 100%; object-fit: cover }
[data-bz-section="location-hero"] .bz-photo--empty { display: none }
[data-bz-section="location-hero"]::after { content: ""; position: absolute; inset: 0; background: rgba(0,0,0,.45); z-index: 1; pointer-events: none }
[data-bz-section="location-hero"] > .bz-container,
[data-bz-section="location-hero"] .bz-row { position: relative; z-index: 2; width: 100% }
[data-bz-section="location-hero"] h1 { color: #fff; font-size: clamp(32px, 4vw, 52px); line-height: 1.15; letter-spacing: -0.02em; margin: 0 0 18px }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] { margin-bottom: 18px }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] p { font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: #e2e2e2; margin: 0 }
[data-bz-section="location-hero"] [data-bz-node^="lh-crumb"] a { color: #e2e2e2 }
[data-bz-section="location-hero"] [data-bz-node^="lh-sub"] p { color: #e2e2e2; font-size: 18px; line-height: 1.6; max-width: 700px; margin: 0 auto 28px }
[data-bz-section="location-hero"] .bz-btns { justify-content: center }
[data-bz-section="location-hero"] .bz-btn--secondary { background: transparent; color: #fff; border: 1px solid rgba(255,255,255,.75) }
